begin;
create function pg_temp.care_assert(ok boolean,label text) returns text language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;return label;end $$;
create function pg_temp.care_denied(stmt text,label text,expected text default '42501') returns text language plpgsql as $$begin begin execute stmt;exception when others then if sqlstate<>expected then raise exception 'Wrong error % for %',sqlstate,label;end if;return label;end;raise exception 'Unexpected success: %',label;end $$;
create function pg_temp.record_p(n integer,kind text,v integer default 0) returns jsonb language sql as $$select jsonb_build_object('id',('d4000000-0000-4000-8000-'||lpad(n::text,12,'0')),'patient_id','d2000000-0000-4000-8000-000000000001','event_id',('d3000000-0000-4000-8000-'||lpad(n::text,12,'0')),'specialty',kind,'version',v,'operation_key',gen_random_uuid(),'occurred_at',now()-interval '2 hours','payload',jsonb_build_object('objective','Objetivo neutro QA','evolution','not_evaluable','facts','Hechos neutros QA'),'reserved_note','','summary_body','','summary_visibility','none','request_intervention',false,'request_body','','request_due_at','','reason','','confirm_finalize',true,'confirm_publish',false)$$;
create temporary table records_fixture(name text primary key,p jsonb);
grant select,insert,update on records_fixture to authenticated;
insert into auth.users(id,email) select ('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'recovery-fixture-'||n||'@example.test' from generate_series(1,7)n;
insert into public.admin_users(user_id,role,is_active) select ('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,(case when n=7 then 'editor' else 'viewer' end)::public.admin_role,true from generate_series(3,7)n;
insert into public.patient_profiles(id,auth_user_id,email,display_name) select ('d2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'recovery-fixture-'||n||'@example.test','Persona record QA '||n from generate_series(1,2)n;
insert into public.care_staff_capabilities(user_id,capabilities) select ('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,array['care.directory.read','care.patient.read','care.records.read','care.records.create']||case when n=5 then array['care.medical.create'] else array[]::text[] end from generate_series(3,5)n;
insert into public.care_staff_capabilities(user_id,capabilities) values('d1000000-0000-4000-8000-000000000006',array['care.directory.read','care.patient.read','care.records.read','care.assignments.manage','care.decisions.manage']);
insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by) select 'd2000000-0000-4000-8000-000000000001',('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case n when 3 then 'psychology' when 4 then 'recovery' when 5 then 'psychiatry' else 'direction' end,now()-interval '1 day','d1000000-0000-4000-8000-000000000006' from generate_series(3,6)n;
insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by) values('d2000000-0000-4000-8000-000000000002','d1000000-0000-4000-8000-000000000006','direction',now()-interval '1 day','d1000000-0000-4000-8000-000000000006');
insert into public.care_events(id,title,kind,starts_at,ends_at,professional_id,modality,status,closed_at,created_by) select ('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Sesión neutra QA '||n,case n when 2 then 'recovery' when 3 then 'psychiatry' else 'individual' end,now()-interval '2 hours',now()-interval '1 hour',('d1000000-0000-4000-8000-'||lpad((case n when 2 then 4 when 3 then 5 when 4 then 6 else 3 end)::text,12,'0'))::uuid,'in_person',case when n=5 then 'cancelled' else 'completed' end,now()-interval '30 minutes',('d1000000-0000-4000-8000-'||lpad((case n when 2 then 4 when 3 then 5 when 4 then 6 else 3 end)::text,12,'0'))::uuid from generate_series(1,6)n;
insert into public.care_event_participants(event_id,patient_id,attendance) select id,'d2000000-0000-4000-8000-000000000001',case when title like '%6' then 'pending' else 'present' end from public.care_events where id::text like 'd3000000-%';

update public.care_staff_capabilities set capabilities=array_append(capabilities,'care.family.read') where user_id in ('d1000000-0000-4000-8000-000000000004','d1000000-0000-4000-8000-000000000006');
update public.care_staff_capabilities set capabilities=array_append(capabilities,'care.records.create') where user_id='d1000000-0000-4000-8000-000000000006';
insert into public.care_events(id,title,kind,starts_at,ends_at,professional_id,modality,status,closed_at,created_by)select ('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Familia QA','family',now()-interval '2 hours',now()-interval '1 hour','d1000000-0000-4000-8000-000000000004','in_person','completed',now(),'d1000000-0000-4000-8000-000000000004' from generate_series(7,8)n;
insert into public.care_event_participants(event_id,patient_id,attendance)select id,'d2000000-0000-4000-8000-000000000001',case when id::text like '%8' then 'pending' else 'absent' end from public.care_events where id::text in ('d3000000-0000-4000-8000-000000000007','d3000000-0000-4000-8000-000000000008');
insert into public.care_session_records(id,patient_id,event_id,author_id,specialty,occurred_at,status,revision,first_finalized_at)values('d4000000-0000-4000-8000-000000000002','d2000000-0000-4000-8000-000000000001','d3000000-0000-4000-8000-000000000002','d1000000-0000-4000-8000-000000000004','recovery',now()-interval '2 hours','final',1,now());
insert into public.care_episodes(patient_id,started_at,status,created_by)values('d2000000-0000-4000-8000-000000000001',now()-interval '5 days','active','d1000000-0000-4000-8000-000000000006');
insert into public.care_events(id,title,kind,starts_at,ends_at,professional_id,modality,status,created_by)values('d3000000-0000-4000-8000-000000000009','Familia prevista QA','family',now()-interval '4 hours',now()-interval '3 hours','d1000000-0000-4000-8000-000000000004','in_person','scheduled','d1000000-0000-4000-8000-000000000004');
insert into public.care_event_participants(event_id,patient_id)values('d3000000-0000-4000-8000-000000000009','d2000000-0000-4000-8000-000000000001');
create function pg_temp.rf(n integer,v integer default 0)returns jsonb language sql as $$select jsonb_build_object('id','d5000000-0000-4000-8000-'||lpad(n::text,12,'0'),'version',v,'patient_id','d2000000-0000-4000-8000-000000000001','record_id','d4000000-0000-4000-8000-000000000002','event_id','d3000000-0000-4000-8000-000000000007','occurred_at',now()-interval '2 hours','dimension','organisation','payload','{"status":"evaluated","evidence":"Evidencia cualitativa QA","level":""}'::jsonb,'confirm_final',true,'reason','Motivo neutro QA')$$;
create function pg_temp.fr(n integer,v integer default 0)returns jsonb language sql as $$select pg_temp.rf(n,v)||jsonb_build_object('reserved_note','Reserva familiar privada QA','payload','{"objective":"Objetivo familiar QA","source":"family_report","participants":[{"label":"Inicial QA","relationship":"Vínculo QA"}],"support":"Apoyo sin inferencia QA"}'::jsonb)$$;
create function pg_temp.rub(n integer,v integer default 0)returns jsonb language sql as $$select pg_temp.rf(n,v)||'{"name":"Instrumento SINTÉTICO QA","ordered":true,"dimensions":[{"key":"schedule","levels":[{"key":"a","label":"Categoría A QA"},{"key":"b","label":"Categoría B QA"}]}]}'::jsonb$$;
