select pg_temp.care_denied($$select public.care_recovery_write('autonomy_final',pg_temp.rf(1,1)||'{"payload":{"status":"evaluated","evidence":"QA evidencia","level":"a"}}'::jsonb)$$,'No level without rubric','P0001');
